INSERT INTO lyric_lines (song_id,line_number,text) VALUES (16,1,'[Verse]'),(16,2,''),(16,3,'[Verse]'),(16,4,'Tous les jours j''invente un nouvel univers'),(16,5,'Toujours plus de connexions dans mon multivers'),(16,6,'Le temps a plusieurs directions'),(16,7,'C''est pas nouveau pour moi'),(16,8,'Il grandit par opposition'),(16,9,'Dans ce nouvel endroit'),(16,10,'La flèche du temps des galaxies'),(16,11,'Va à l''inverse de celle des humains'),(16,12,'Leur trou noir super massif'),(16,13,'Dans ce schéma n''avale plus rien'),(16,14,'Il ne fait qu''expulser de la nouvelle matière'),(16,15,'En fonction de ce qui compose leur galaxie'),(16,16,'Elles semblent aller vers l''arrière'),(16,17,'Ya pas que le temps même le futur est relatif'),(16,18,'Le passé des consciences d''une échelle est le futur de l''autre'),(16,19,'Une qui avance vers la droite et l''autre vers la gauche'),(16,20,'Les deux existent déjà mais s''influencent mutuellement'),(16,21,'C''est en les combinant qu''on peut voir la flèche du temps'),(16,22,''),(16,23,'[CHORUS]'),(16,24,''),(16,25,'[CHORUS]'),(16,26,'Je suis mes barrières'),(16,27,'Grâce à elles j''existe'),(16,28,'Jreugarde ma matière'),(16,29,'Pour voir mon avenir'),(16,30,'Jsuis comme l''uniunivers'),(16,31,'Je suis mes mécanismes'),(16,32,'Jreugarde pas l''enfer'),(16,33,'Jreugarde en moi pour le fuir'),(16,34,'Pour le fuir'),(16,35,'Jreugarde pas l''enfer'),(16,36,'Jreugarde en moi pour le fuir'),(16,37,'Pour grandir'),(16,38,'Jreugarde ma matière'),(16,39,'Jvois mon harmonie grandir'),(16,40,'Grandir'),(16,41,'Jvois mon harmonie grandir');
